import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

public class BankVaultTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        BankVault v = new BankVault();
        check("new vault starts at 0.0", 0.0, v.getBalance());

        v.deposit(100.0);
        check("after deposit(100.0)", 100.0, v.getBalance());

        v.deposit(-25.0);
        check("deposit(-25.0) is ignored", 100.0, v.getBalance());

        v.withdraw(40.0);
        check("after withdraw(40.0)", 60.0, v.getBalance());
        check("isOverdrawn() at 60.0", false, v.isOverdrawn());

        v.withdraw(100.0);
        check("overdrawn balance and flag", "-40.0 true", v.getBalance() + " " + v.isOverdrawn());

        // auditReset() has no access modifier, so only same-package code (this test) may call it.
        v.auditReset();
        check("after auditReset()", 0.0, v.getBalance());

        // Encapsulation: every declared field must be private, so callers cannot bypass the methods.
        boolean allPrivate = true;
        int fieldCount = 0;
        for (Field f : BankVault.class.getDeclaredFields()) {
            if (f.isSynthetic()) {
                continue;
            }
            fieldCount++;
            if (!Modifier.isPrivate(f.getModifiers())) {
                allPrivate = false;
            }
        }
        check("exactly one field, and it is private", true, fieldCount == 1 && allPrivate);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

