public class BankVault {

    private double balance;

    public double getBalance() {
        return balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public void withdraw(double amount) {
        balance -= amount;
    }

    void auditReset() {
        balance = 0.0;
    }

    protected boolean isOverdrawn() {
        return balance < 0.0;
    }
}
